/** Split physical variants must keep their identities when admission declines before an executable exists. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativePackedVariantInventoryTest {
	private final Map<String, String> previous = new LinkedHashMap<>();

	@BeforeEach
	void configure() {
		set("rdf4j.lmdb.packedFtree.enabled", "true");
		set("rdf4j.lmdb.packedFtree.parallel.enabled", "true");
		set("rdf4j.lmdb.parallel.enabled", "true");
		set("rdf4j.lmdb.parallel.threads", "4");
		set("rdf4j.lmdb.parallel.maxTasks", "4");
		set("rdf4j.lmdb.packedFtree.parallel.minRootsPerPartition", "128");
		set(LmdbNativePackedMorsels.ROWS_PROPERTY, "128");
	}

	@AfterEach
	void restore() {
		previous.forEach((name, value) -> {
			if (value == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, value);
			}
		});
	}

	@Test
	void availableBudgetNamesBothAdmittedPhysicalVariantsWithoutReservingThem() throws Exception {
		LmdbNativeDecisionRecord record = preview();
		assertThat(record.entries()).filteredOn(LmdbNativeDecisionRecord.Entry::admitted)
				.extracting(LmdbNativeDecisionRecord.Entry::id)
				.containsExactly(LmdbNativePackedFtree.ROWS_SERIAL, LmdbNativePackedFtree.ROWS_PARALLEL);
		try (var capacity = LmdbNativeParallelPipelines.tryReserveTasks(false, 4)) {
			assertThat(capacity).as("preview must not take any task slots").isNotNull();
			assertThat(capacity.grantedWorkers()).isEqualTo(4);
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 3, 4 })
	void taskBudgetDeclineKeepsTheExactParallelVariantIdentity(int occupied) throws Exception {
		try (var holder = LmdbNativeParallelPipelines.tryReserveTasks(false, occupied)) {
			assertThat(holder).isNotNull();
			assertThat(holder.grantedWorkers()).isEqualTo(occupied);
			LmdbNativeDecisionRecord record = preview();
			assertThat(record.entries()).filteredOn(LmdbNativeDecisionRecord.Entry::admitted)
					.extracting(LmdbNativeDecisionRecord.Entry::id)
					.containsExactly(LmdbNativePackedFtree.ROWS_SERIAL);
			assertThat(record.entries()).filteredOn(entry -> !entry.admitted())
					.as("the declined peer must remain recognizable as packedFtree(parallel), not an anonymous offer")
					.extracting(LmdbNativeDecisionRecord.Entry::id)
					.containsExactly(LmdbNativePackedFtree.ROWS_PARALLEL);
			assertThat(record.entries()).filteredOn(entry -> !entry.admitted())
					.allSatisfy(entry -> assertThat(entry.declineReason()).isNotBlank());
		}
		try (var restored = LmdbNativeParallelPipelines.tryReserveTasks(false, 4)) {
			assertThat(restored).isNotNull();
			assertThat(restored.grantedWorkers()).isEqualTo(4);
		}
	}

	private static LmdbNativeDecisionRecord preview() throws Exception {
		NativeLmdbQuerySource source = new StatsSource(10_000L).predicate(1L, 1D, 500L)
				.predicate(2L, 1D, 500L)
				.adjacencyServed(true);
		RowState row = row(source);
		MultiJoinPlan input = new MultiJoinPlan(new SlotPlan[] { edge(0, 1L, 1, 500D), edge(0, 2L, 2, 500D) },
				new MaskedFilter[0]);
		try (QueryExplanationContext ignored = QueryExplanationContext.enter(Explanation.Level.Optimized)) {
			// Exactly the serial/parallel offer composition used by NativeRowsStep. No candidate opener is called.
			LmdbNativeOffers<NativeUnorderedInput> offers = new LmdbNativeOffers<>(
					LmdbNativeDecisionPoint.ROW);
			offers.offer(() -> LmdbNativePackedFtree.proposeRows((SlotPlan) input, row, new int[] { 0, 1, 2 }, false,
					null));
			offers.offer(() -> LmdbNativePackedFtree.proposeParallelRows(input, row, new int[] { 0, 1, 2 }, false,
					null));
			return new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW, offers.strategies(), null).preview(null);
		} finally {
			row.memoryScope.close();
		}
	}

	private void set(String name, String value) {
		if (!previous.containsKey(name)) {
			previous.put(name, System.getProperty(name));
		}
		System.setProperty(name, value);
	}
}
